CREATE TEMP TABLE source AS SELECT
    "Call  Failure" AS failures, Complains AS complaint,
    "Subscription  Length" AS tenure, "Charge  Amount" AS charge,
    "Seconds of Use" AS seconds, "Frequency of use" AS calls,
    "Frequency of SMS" AS sms, "Distinct Called Numbers" AS distinct_calls,
    "Age Group" AS age_group, "Tariff Plan" AS tariff, Status AS status,
    Age AS age, "Customer Value" AS value, Churn AS churn
    FROM read_csv_auto('/hal-light/examples/iranian-telecom-churn-local/question/data.csv');

CREATE TEMP TABLE source_dedup AS SELECT DISTINCT * FROM temp.main.source;

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.source WHERE true;

SELECT sum(n) AS n, sum(events) AS churners,
        sum(event_value) AS churn_value FROM (
          SELECT complaint,status,count(*) AS n,sum(churn) AS events,
            sum(value*churn) AS event_value
          FROM temp.main.source GROUP BY complaint,status);

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.source WHERE status=1;

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.source_dedup WHERE true;

SELECT sum(n) AS n, sum(events) AS churners,
        sum(event_value) AS churn_value FROM (
          SELECT complaint,status,count(*) AS n,sum(churn) AS events,
            sum(value*churn) AS event_value
          FROM temp.main.source_dedup GROUP BY complaint,status);

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.source_dedup WHERE status=1;

CREATE OR REPLACE TEMP TABLE base AS SELECT *,hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value) AS profile,
          CASE WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261105)%100<60 THEN 'train'
               WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261105)%100<80 THEN 'validation'
               ELSE 'test' END AS split FROM temp.main.source;

SELECT split,count(*) AS n,sum(churn) AS churners,
            avg(churn) AS prevalence,count(DISTINCT profile) AS profiles
            FROM temp.main.base GROUP BY split ORDER BY split;

SELECT count(*) AS n FROM (
            SELECT profile FROM temp.main.base GROUP BY profile HAVING count(DISTINCT split)>1);

SELECT median(seconds) FILTER (WHERE seconds>0) AS positive_seconds_median,
            avg(churn) AS prior FROM temp.main.base WHERE split='train';

CREATE OR REPLACE TEMP TABLE data AS SELECT *,
            CASE WHEN seconds=0 THEN 0 WHEN seconds<=3207.5 THEN 1
            ELSE 2 END AS usage FROM temp.main.base;

CREATE OR REPLACE TEMP TABLE fit_complaint AS
                SELECT complaint, count(*) AS n, sum(churn) AS events,
                  (sum(churn)+20*0.15158007498660953)/(count(*)+20) AS risk
                FROM temp.main.data WHERE split='train' GROUP BY complaint;

SELECT max(abs(risk*(n+20)-events-20*0.15158007498660953)) AS residual,
                sum(n) AS n,sum(events) AS events FROM temp.main.fit_complaint;

CREATE OR REPLACE TEMP TABLE pred_complaint AS
                SELECT d.*,coalesce(f.risk,0.15158007498660953) AS risk
                FROM temp.main.data AS d LEFT JOIN temp.main.fit_complaint AS f USING (complaint);

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.pred_complaint WHERE split='validation';

WITH cells AS (
        SELECT risk, count(*) AS n, sum(churn) AS events
        FROM temp.main.pred_complaint WHERE split='validation' GROUP BY risk
      ), ordered AS (
        SELECT *, coalesce(sum(n-events) OVER (ORDER BY risk
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS neg_below
        FROM cells
      ) SELECT sum(events*(neg_below+0.5*(n-events))) /
          nullif(sum(events)*sum(n-events),0) AS auc,
        sum(events*pow(1-risk,2)+(n-events)*pow(risk,2))/sum(n) AS brier,
        sum(n*risk)/sum(n) AS mean_prediction
      FROM ordered;

SELECT avg(pow(risk-churn,2)) AS brier
        FROM temp.main.pred_complaint WHERE split='validation';

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.pred_complaint WHERE split='validation';

WITH cells AS (
        SELECT risk, count(*) AS n, sum(churn) AS events,
          sum(value*churn) AS event_value
        FROM temp.main.pred_complaint WHERE (split='validation') AND (true) GROUP BY risk
      ), ordered AS (
        SELECT *, coalesce(sum(n) OVER (ORDER BY risk DESC
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS above
        FROM cells
      ) SELECT coalesce(sum(n),0) AS eligible_n,
        coalesce(sum(CASE WHEN above+n<=137 THEN n ELSE 0 END),0) AS full_n,
        coalesce(sum(CASE WHEN above+n<=137 THEN events ELSE 0 END),0) AS full_events,
        coalesce(sum(CASE WHEN above+n<=137 THEN event_value ELSE 0 END),0) AS full_value,
        coalesce(sum(CASE WHEN above<137 AND above+n>137 THEN n ELSE 0 END),0) AS boundary_n,
        coalesce(sum(CASE WHEN above<137 AND above+n>137 THEN events ELSE 0 END),0) AS boundary_events,
        coalesce(sum(CASE WHEN above<137 AND above+n>137 THEN event_value ELSE 0 END),0) AS boundary_value
      FROM ordered;

