CREATE OR REPLACE TEMP TABLE base AS SELECT *,hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value) AS profile,
          CASE WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261106)%100<60 THEN 'train'
               WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261106)%100<80 THEN 'validation'
               ELSE 'test' END AS split FROM temp.main.source_dedup;

