        FROM temp.main.pred_complaint_usage_status WHERE split='test' AND status=1;

WITH cells AS (
        SELECT complaint,seconds, count(*) AS n, sum(churn) AS events,
          sum(value*churn) AS event_value
        FROM temp.main.pred_complaint_usage_status WHERE (split='test' AND status=1) AND (true) GROUP BY complaint,seconds
      ), ordered AS (
        SELECT *, coalesce(sum(n) OVER (ORDER BY complaint DESC,seconds ASC
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS above
        FROM cells
      ) SELECT coalesce(sum(n),0) AS eligible_n,
        coalesce(sum(CASE WHEN above+n<=96 THEN n ELSE 0 END),0) AS full_n,
        coalesce(sum(CASE WHEN above+n<=96 THEN events ELSE 0 END),0) AS full_events,
        coalesce(sum(CASE WHEN above+n<=96 THEN event_value ELSE 0 END),0) AS full_value,
        coalesce(sum(CASE WHEN above<96 AND above+n>96 THEN n ELSE 0 END),0) AS boundary_n,
        coalesce(sum(CASE WHEN above<96 AND above+n>96 THEN events ELSE 0 END),0) AS boundary_events,
        coalesce(sum(CASE WHEN above<96 AND above+n>96 THEN event_value ELSE 0 END),0) AS boundary_value
      FROM ordered;

WITH ranked AS (
        SELECT status, churn, value,
          rank() OVER (ORDER BY risk DESC) AS first_rank,
          count(*) OVER (PARTITION BY risk) AS tie_n
        FROM temp.main.pred_complaint_usage_status WHERE split='test' AND status=1
      ), weighted AS (
        SELECT *, least(1.0,greatest(0.0,(96-first_rank+1)*1.0/tie_n)) AS w
        FROM ranked
      ) SELECT status, sum(w) AS contacts, sum(w*churn) AS caught,
        sum(w*churn*value) AS caught_value FROM weighted GROUP BY status;

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.pred_complaint_usage_status WHERE split='test' AND status=1 AND complaint=1;

