CREATE OR REPLACE TEMP TABLE base AS SELECT *,hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value) AS profile,
          CASE WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261119)%100<60 THEN 'train'
               WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261119)%100<80 THEN 'validation'
               ELSE 'test' END AS split FROM temp.main.source_dedup;

SELECT split,count(*) AS n,sum(churn) AS churners,
            avg(churn) AS prevalence,count(DISTINCT profile) AS profiles
            FROM temp.main.base GROUP BY split ORDER BY split;

SELECT count(*) AS n FROM (
            SELECT profile FROM temp.main.base GROUP BY profile HAVING count(DISTINCT split)>1);

SELECT median(seconds) FILTER (WHERE seconds>0) AS positive_seconds_median,
            avg(churn) AS prior FROM temp.main.base WHERE split='train';

CREATE OR REPLACE TEMP TABLE data AS SELECT *,
            CASE WHEN seconds=0 THEN 0 WHEN seconds<=3342.5 THEN 1
            ELSE 2 END AS usage FROM temp.main.base;

CREATE OR REPLACE TEMP TABLE fit_complaint AS
                SELECT complaint, count(*) AS n, sum(churn) AS events,
                  (sum(churn)+20*0.14224924012158055)/(count(*)+20) AS risk
