          CASE WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261121)%100<60 THEN 'train'
               WHEN hash(failures,complaint,tenure,charge,seconds,calls,sms,distinct_calls,age_group,tariff,status,age,value,20261121)%100<80 THEN 'validation'
               ELSE 'test' END AS split FROM temp.main.source;

