        FROM temp.main.pred_complaint_usage_status WHERE split='test';

WITH cells AS (
        SELECT risk, count(*) AS n, sum(churn) AS events
        FROM temp.main.pred_complaint_usage_status WHERE split='test' GROUP BY risk
      ), ordered AS (
        SELECT *, coalesce(sum(n-events) OVER (ORDER BY risk
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS neg_below
        FROM cells
      ) SELECT sum(events*(neg_below+0.5*(n-events))) /
          nullif(sum(events)*sum(n-events),0) AS auc,
        sum(events*pow(1-risk,2)+(n-events)*pow(risk,2))/sum(n) AS brier,
        sum(n*risk)/sum(n) AS mean_prediction
      FROM ordered;

SELECT avg(pow(risk-churn,2)) AS brier
        FROM temp.main.pred_complaint_usage_status WHERE split='test';

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.pred_complaint_usage_status WHERE split='test';

WITH cells AS (
        SELECT risk, count(*) AS n, sum(churn) AS events,
          sum(value*churn) AS event_value
        FROM temp.main.pred_complaint_usage_status WHERE (split='test') AND (true) GROUP BY risk
      ), ordered AS (
        SELECT *, coalesce(sum(n) OVER (ORDER BY risk DESC
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS above
        FROM cells
      ) SELECT coalesce(sum(n),0) AS eligible_n,
        coalesce(sum(CASE WHEN above+n<=123 THEN n ELSE 0 END),0) AS full_n,
        coalesce(sum(CASE WHEN above+n<=123 THEN events ELSE 0 END),0) AS full_events,
        coalesce(sum(CASE WHEN above+n<=123 THEN event_value ELSE 0 END),0) AS full_value,
        coalesce(sum(CASE WHEN above<123 AND above+n>123 THEN n ELSE 0 END),0) AS boundary_n,
        coalesce(sum(CASE WHEN above<123 AND above+n>123 THEN events ELSE 0 END),0) AS boundary_events,
        coalesce(sum(CASE WHEN above<123 AND above+n>123 THEN event_value ELSE 0 END),0) AS boundary_value
      FROM ordered;

WITH ranked AS (
        SELECT status, churn, value,
          rank() OVER (ORDER BY risk DESC) AS first_rank,
          count(*) OVER (PARTITION BY risk) AS tie_n
        FROM temp.main.pred_complaint_usage_status WHERE split='test'
      ), weighted AS (
        SELECT *, least(1.0,greatest(0.0,(123-first_rank+1)*1.0/tie_n)) AS w
        FROM ranked
      ) SELECT status, sum(w) AS contacts, sum(w*churn) AS caught,
        sum(w*churn*value) AS caught_value FROM weighted GROUP BY status;

