CREATE OR REPLACE TEMP TABLE fit_complaint_usage AS
                SELECT complaint,usage, count(*) AS n, sum(churn) AS events,
                  (sum(churn)+20*0.15146198830409358)/(count(*)+20) AS risk
                FROM temp.main.data WHERE split='train' GROUP BY complaint,usage;

SELECT max(abs(risk*(n+20)-events-20*0.15146198830409358)) AS residual,
                sum(n) AS n,sum(events) AS events FROM temp.main.fit_complaint_usage;

CREATE OR REPLACE TEMP TABLE pred_complaint_usage AS
                SELECT d.*,coalesce(f.risk,0.15146198830409358) AS risk
                FROM temp.main.data AS d LEFT JOIN temp.main.fit_complaint_usage AS f USING (complaint,usage);

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.pred_complaint_usage WHERE split='validation';

WITH cells AS (
        SELECT risk, count(*) AS n, sum(churn) AS events
        FROM temp.main.pred_complaint_usage WHERE split='validation' GROUP BY risk
      ), ordered AS (
        SELECT *, coalesce(sum(n-events) OVER (ORDER BY risk
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS neg_below
        FROM cells
      ) SELECT sum(events*(neg_below+0.5*(n-events))) /
          nullif(sum(events)*sum(n-events),0) AS auc,
        sum(events*pow(1-risk,2)+(n-events)*pow(risk,2))/sum(n) AS brier,
        sum(n*risk)/sum(n) AS mean_prediction
      FROM ordered;

SELECT avg(pow(risk-churn,2)) AS brier
        FROM temp.main.pred_complaint_usage WHERE split='validation';

SELECT count(*) AS n, coalesce(sum(churn),0) AS churners,
        coalesce(sum(churn*value),0) AS churn_value, avg(churn) AS prevalence
        FROM temp.main.pred_complaint_usage WHERE split='validation';

WITH cells AS (
        SELECT risk, count(*) AS n, sum(churn) AS events,
          sum(value*churn) AS event_value
        FROM temp.main.pred_complaint_usage WHERE (split='validation') AND (true) GROUP BY risk
      ), ordered AS (
        SELECT *, coalesce(sum(n) OVER (ORDER BY risk DESC
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS above
        FROM cells
      ) SELECT coalesce(sum(n),0) AS eligible_n,
        coalesce(sum(CASE WHEN above+n<=110 THEN n ELSE 0 END),0) AS full_n,
        coalesce(sum(CASE WHEN above+n<=110 THEN events ELSE 0 END),0) AS full_events,
        coalesce(sum(CASE WHEN above+n<=110 THEN event_value ELSE 0 END),0) AS full_value,
        coalesce(sum(CASE WHEN above<110 AND above+n>110 THEN n ELSE 0 END),0) AS boundary_n,
        coalesce(sum(CASE WHEN above<110 AND above+n>110 THEN events ELSE 0 END),0) AS boundary_events,
        coalesce(sum(CASE WHEN above<110 AND above+n>110 THEN event_value ELSE 0 END),0) AS boundary_value
      FROM ordered;

