        coalesce(sum(CASE WHEN above<90 AND above+n>90 THEN events ELSE 0 END),0) AS boundary_events,
        coalesce(sum(CASE WHEN above<90 AND above+n>90 THEN event_value ELSE 0 END),0) AS boundary_value
      FROM ordered;

